import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Function to make API request
async function importTemplates() {
  try {
    // Read the processed templates
    const templatesPath = path.join(__dirname, 'processed-templates.json');
    const templatesData = JSON.parse(fs.readFileSync(templatesPath, 'utf8'));

    console.log(`🚀 Importing ${templatesData.length} templates...`);

    const response = await fetch('http://localhost:5000/api/content-templates/import-excel', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ templates: templatesData }),
    });

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const result = await response.json();

    console.log('✅ Import completed:');
    console.log(`   Updated: ${result.updated}`);
    console.log(`   Total processed: ${result.total}`);
    console.log(`   Message: ${result.message}`);

  } catch (error) {
    console.error('❌ Error importing templates:', error);
  }
}

// Run the import
importTemplates();

