import XLSX from 'xlsx';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Read the Excel file
const filePath = path.join(__dirname, '..', 'attached_assets', 'Enlaces e ideas_1758367864318.xlsx');

try {
  // Read the file as binary
  const data = fs.readFileSync(filePath);
  const workbook = XLSX.read(data, { type: 'buffer' });

  console.log('=== EXCEL FILE ANALYSIS ===');
  console.log('Sheet names:', workbook.SheetNames);

  // Process each sheet
  workbook.SheetNames.forEach(sheetName => {
    console.log(`\n=== SHEET: ${sheetName} ===`);
    const worksheet = workbook.Sheets[sheetName];
    const jsonData = XLSX.utils.sheet_to_json(worksheet, { header: 1 });

    console.log('Headers (first row):', jsonData[0]);
    console.log('Total rows:', jsonData.length);

    // Show first 5 data rows
    console.log('\nFirst 5 data rows:');
    for (let i = 1; i <= Math.min(5, jsonData.length - 1); i++) {
      console.log(`Row ${i}:`, jsonData[i]);
    }

    // Convert to objects for better analysis
    if (jsonData.length > 1) {
      const headers = jsonData[0];
      const objects = jsonData.slice(1).map(row => {
        const obj = {};
        headers.forEach((header, index) => {
          obj[header] = row[index];
        });
        return obj;
      });

      console.log('\nSample object format:');
      console.log(JSON.stringify(objects[0], null, 2));
    }
  });

} catch (error) {
  console.error('Error reading Excel file:', error);
}

