                }
              }}
              data-testid="input-campaign-file"
            />
          </div>
        </DialogContent>
      </Dialog>

      {/* Add Campaign Modal */}
      <Dialog open={showAddCampaignModal} onOpenChange={setShowAddCampaignModal}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>Add Campaign</DialogTitle>
            <DialogDescription>
