              <Button onClick={handleAddCampaign} disabled={!newCampaignName.trim() || addCampaignMutation.isPending}>
                {addCampaignMutation.isPending ? "Adding..." : "Add Campaign"}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

