import XLSX from 'xlsx';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Read the Excel file
const filePath = path.join(__dirname, '..', 'attached_assets', 'Enlaces e ideas_1758367864318.xlsx');

function extractVideoLink(text) {
  const linkMatch = text.match(/https:\/\/www\.youtube\.com\/shorts\/[A-Za-z0-9_-]+/);
  return linkMatch ? linkMatch[0] : '';
}

function extractIdea(text) {
  const ideaMatch = text.match(/[""]([^""]*)[""]/);
  return ideaMatch ? ideaMatch[1] : '';
}

function extractViews(text) {
  const viewsMatch = text.match(/(\d+k?\s*views)/i);
  return viewsMatch ? viewsMatch[1] : '';
}

function extractProposal(text) {
  const proposalMatch = text.match(/I propose the following content idea:\s*[""]([^""]*)[""]/);
  return proposalMatch ? proposalMatch[1] : '';
}

try {
  const data = fs.readFileSync(filePath);
  const workbook = XLSX.read(data, { type: 'buffer' });
  const worksheet = workbook.Sheets['Sheet1'];
  const jsonData = XLSX.utils.sheet_to_json(worksheet, { header: 1 });

  const headers = jsonData[0];
  const processedData = jsonData.slice(1).map(row => {
    const nicho = row[0];
    const content = row[1] || '';

    return {
      nicho: nicho,
      originalIdea: extractIdea(content),
      videoLink: extractVideoLink(content),
      views: extractViews(content),
      proposedIdea: extractProposal(content),
      fullTemplate: content
    };
  }).filter(item => item.nicho); // Filter out empty rows

  console.log('=== PROCESSED TEMPLATES ===');
  console.log(`Total templates: ${processedData.length}`);

  console.log('\nSample processed template:');
  console.log(JSON.stringify(processedData[0], null, 2));

  console.log('\nAll niches found:');
  const niches = [...new Set(processedData.map(item => item.nicho))].sort();
  console.log(niches);

  // Save processed data to file for import
  fs.writeFileSync(
    path.join(__dirname, 'processed-templates.json'), 
    JSON.stringify(processedData, null, 2)
  );

  console.log('\n✅ Processed data saved to scripts/processed-templates.json');

} catch (error) {
  console.error('Error processing templates:', error);
}

